def _redact_gh_error(text: str) -> str:
    try:
        redacted = redact.redact(text)
    except Exception:
        return "gh stderr redaction failed"
    if "[content truncated" in redacted:
        return "gh stderr redaction unavailable"
    flat = redacted.replace("\r", " ").replace("\n", " ")
    return flat[:500]


